#!/usr/bin/env sh
# Compiles the Python dependencies into lock files with pinned versions and hashes.
#
#   scripts/lock.sh            regenerates backend/requirements.txt and requirements-dev.txt
#   scripts/lock.sh --upgrade  same, but takes the newest versions the ranges allow
#
# Edit backend/requirements.in (and requirements-dev.in) to declare what the project needs, then run this.
# The generated files are what the images install, with "pip install --require-hashes": a build either gets
# exactly these versions and these file hashes, or it fails. Docker is the only prerequisite.
#
# Resolution happens in the image the backend is built from (python:3.12-slim), so the versions and the
# markers match the runtime. --generate-hashes collects the hashes of every distribution of each release, so
# the lock also installs on another architecture as long as the publisher built a wheel for it.
set -eu

MSYS_NO_PATHCONV=1
MSYS2_ARG_CONV_EXCL='*'
export MSYS_NO_PATHCONV MSYS2_ARG_CONV_EXCL

cd "$(dirname "$0")/.."
REPO=$(pwd)
PYTHON_IMAGE=${PYTHON_IMAGE:-python:3.12-slim}
UV_VERSION=${UV_VERSION:-0.13.4}
UPGRADE=""
[ "${1:-}" = "--upgrade" ] && UPGRADE="--upgrade"

docker run --rm -v "$REPO/backend:/b" -w /b "$PYTHON_IMAGE" sh -eu -c "
    pip install --quiet --no-cache-dir 'uv==$UV_VERSION'
    for name in requirements requirements-dev; do
        uv pip compile \$name.in \
            --generate-hashes \
            --no-header \
            --output-file \$name.txt \
            --quiet $UPGRADE
        # The header says where the file comes from, so nobody edits it by hand
        printf '%s\n%s\n%s\n%s\n\n' \
            '# Generated by scripts/lock.sh from '\$name'.in - do not edit.' \
            '# Pinned versions and file hashes: the images install this file with' \
            '#   pip install --require-hashes -r '\$name'.txt' \
            '# Add or change a dependency in '\$name'.in, then run scripts/lock.sh.' \
            | cat - \$name.txt > \$name.txt.new && mv \$name.txt.new \$name.txt
        printf 'wrote %s (%s pinned packages)\n' \$name.txt \$(grep -c '^[a-zA-Z0-9]' \$name.txt)
    done
"

printf '\nReview the diff, then rebuild: make build (or docker compose build --pull)\n'
